(function(root){'use strict';
 function dimensions(width,height,maxWidth=624,maxHeight=480){let ratio=Math.min(maxWidth/width,maxHeight/height,1);return {width:Math.round(width*ratio),height:Math.round(height*ratio)}}
 function createDocument(lib,{project,record,activity,photos=[]}){const {Document,Paragraph,TextRun,HeadingLevel,ImageRun,AlignmentType}=lib;const text=x=>String(x??'').trim()||'Não informado';const fmt=s=>s&&/^\d{4}-\d{2}-\d{2}$/.test(s)?s.split('-').reverse().join('/'):text(s);let children=[];
 const p=(v,opt={})=>new Paragraph({children:String(v).split('\n').flatMap((line,i)=>[...(i?[new TextRun({break:1})]:[]),new TextRun({text:line})]),spacing:{after:140,line:276},...opt});
 const heading=(v)=>new Paragraph({text:v,heading:HeadingLevel.HEADING_2,spacing:{before:220,after:120},keepNext:true});
 const section=(title,value)=>{children.push(heading(title),p(text(value)))};
 children.push(new Paragraph({text:'Diário de obra',heading:HeadingLevel.TITLE,spacing:{after:140}}),p(project.id+'  '+project.name,{spacing:{after:100}}),p('Data do registro: '+fmt(record.date)),p('Local: '+text(project.location)),p('Responsável: '+text(project.owner)),p('Registro: '+record.id,{spacing:{after:180}}));
 section('Condições e equipe',`Condições do dia: ${text(record.conditions)}\nEquipes presentes: ${text(record.team)}${record.hours?'\nHoras-pessoa registradas: '+record.hours:''}`);
 section('Serviços executados',record.description);if(activity)children.push(p(`Serviço vinculado: ${activity.id}\n${activity.name}\nQuantidade adicional deste registro: ${record.quantity||0} ${activity.unit}`));
 section('Materiais e equipamentos',`Materiais: ${text(record.materials)}\nEquipamentos: ${text(record.equipment)}`);
 section('Inspeções e liberações',record.inspections);section('Interferências e pendências',record.interference);section('Orientações recebidas',record.instructions);section('Planejamento do próximo dia',record.nextDay);
 if(record.evidence)section('Referências de evidências',record.evidence);
 children.push(p('Registro interno de acompanhamento da execução.',{spacing:{before:200,after:100}}));
 photos.forEach((photo,i)=>{let size=dimensions(photo.width,photo.height);let image=new ImageRun({type:photo.dataURL.startsWith('data:image/png')?'png':'jpg',data:photo.dataURL,transformation:size,altText:{title:'Foto '+(i+1),description:photo.caption||photo.name||'Registro fotográfico',name:photo.name||'Foto '+(i+1)}});children.push(new Paragraph({text:'Registro fotográfico',heading:HeadingLevel.HEADING_1,pageBreakBefore:true,spacing:{after:160},keepNext:true}),p('Foto '+(i+1)+' de '+photos.length,{keepNext:true}),new Paragraph({children:[image],alignment:AlignmentType.CENTER,spacing:{after:140},keepNext:true}),p(text(photo.caption||photo.name)),p('Arquivo: '+text(photo.name),{spacing:{after:80}}));});
 return new Document({creator:'Obras dos Lagos',title:'Diário de obra '+project.name+' '+fmt(record.date),description:'Registro diário da execução com fotografias',styles:{default:{document:{run:{font:'Arial',size:22,color:'000000'},paragraph:{spacing:{line:276,after:140}}}},paragraphStyles:[{id:'Title',name:'Title',basedOn:'Normal',next:'Normal',quickFormat:true,run:{font:'Arial',size:36,bold:true,color:'000000'},paragraph:{spacing:{after:160}}},{id:'Heading1',name:'heading 1',basedOn:'Normal',next:'Normal',quickFormat:true,run:{font:'Arial',size:28,bold:true,color:'000000'},paragraph:{keepNext:true}},{id:'Heading2',name:'heading 2',basedOn:'Normal',next:'Normal',quickFormat:true,run:{font:'Arial',size:24,bold:true,color:'000000'},paragraph:{keepNext:true}}]},sections:[{properties:{page:{size:{width:12240,height:15840},margin:{top:1080,bottom:1080,left:1080,right:1080}}},children}]});
 }
 function filename(project,record){return ('Diario_'+project.id+'_'+(record.date||'sem-data')+'_'+record.id).replace(/[^A-Za-z0-9_-]/g,'_')+'.docx'}
 const api={createDocument,dimensions,filename};if(typeof module!=='undefined'&&module.exports)module.exports=api;else root.ObrasDiaryDocx=api;
})(typeof window==='undefined'?globalThis:window);
